fn put64(out:[*]u8,pos:usize,value:i64)void{const u:u64=@bitCast(value);for(0..8)|j|out[pos+j]=@truncate(u>>(8*j));}
pub export fn edn_lattice_synthesis(raw:?[*]const i64,n:usize,out:?[*]u8,cap:usize)i64{const v=raw orelse return -1;if(n<2 or n>34)return -1;const order=v[0];var f=v[1];if(order<1 or order>16 or f< -65536 or f>65535 or n!=2+2*@as(usize,@intCast(order)))return -1;const q:usize=@intCast(order);var b=[_]i64{0}**16;var k=[_]i64{0}**16;for(0..q)|i|{b[i]=v[2+i];k[i]=v[2+q+i];if(b[i]< -1024 or b[i]>1023 or k[i]< -1024 or k[i]>1023)return -1;}const bytes=8*(q+1);const o=out orelse return -2;if(cap<bytes)return -2;f-=b[q-1]*k[q-1];var z=q;while(z>1){z-=1;const i=z-1;f-=b[i]*k[i];b[i+1]=b[i]+((k[i]*(f>>16))>>16);}b[0]=f>>16;put64(o,0,f);for(0..q)|i|put64(o,8*(i+1),b[i]);return @intCast(bytes);}
